import yt_dlp
import deezer
from mutagen.easyid3 import EasyID3
from mutagen.id3 import ID3, APIC
import requests
from ytmusicapi import YTMusic
import time

from config import print_log, illegal_characters

class Downloader():
    def __init__(self,track:deezer.Track,settings: dict):
        self.track = track
        self.settings = settings
        self.filename = illegal_characters(f"{self.track.artist.name} - {self.track.title}.mp3")
        self.path = self.settings['path'].replace(".","")

    def download(self) -> bool:
        # YT-DLP SETTINGS | generated by https://github.com/yt-dlp/yt-dlp/blob/master/devscripts/cli_to_api.py

        DL_SETTINGS = {'final_ext': 'mp3', 'no_warnings': True, 'quiet': True, 'format': 'bestaudio/best',
        'outtmpl': {'default': self.path+self.filename},
        'postprocessors': [{'key': 'FFmpegExtractAudio',
                            'nopostoverwrites': False,
                            'preferredcodec': 'mp3',
                            'preferredquality': '5'}]}
        
        downloader = yt_dlp.YoutubeDL(DL_SETTINGS)
        ytm = YTMusic()

        for x in range(5):
            try:
                search_results = ytm.search(query=f"{self.track.artist.name} {self.track.title}", filter="songs")

                if not search_results:
                    print_log("Error", f"Could not find any results for {self.track.artist.name} - {self.track.title}")
                    time.sleep(0.1)
                else:
                    query = f"https://www.youtube.com/watch?v={search_results[0]['videoId']}"
                    print_log("Query",query)
                    downloader.download(query)
                    return True
            except Exception as e:
                print_log(f"Error", str(e))
        print_log("Timeout", "Please retry after the process has finished")
        return False

    def embed_data(self):
        try:
            audio = EasyID3(self.path+self.filename)
            audio["albumartist"] = self.track.album.artist.name
            audio["artist"] = self.track.artist.name
            audio["album"] = self.track.album.title
            audio["title"] = self.track.title
            audio["tracknumber"] = f"{self.track.track_position}/{len(self.track.album.tracks)}"
            audio["date"] = str(self.track.release_date)
            genre = self.track.album.genres[0].name if self.track.album.genres else ""
            audio["genre"] = genre
            audio.save()
        except Exception as e:
            raise e

    def embed_cover(self):
        try:
            url = self.track.album.cover_medium
            audio = ID3(self.path+self.filename)
            audio.delall("APIC")
            audio.add(APIC(encoding=3,mime="image/jpeg",type=3,# 3 = front cover
                desc="Cover",data=requests.get(url).content))
            audio.save(v2_version=3)
        except Exception as e:
            raise e